SELECT DISTINCT ?minThroughput WHERE {
  ?dimensioning a :Cl_ThroughputDimensioning ;
                 :hasMinimumThroughputKbps ?minThroughput ;
                 :isDimensionedOn ?sharedResource .
  ?sharedResource a :Cl_SharedNetworkResource ;
                  :appliesToNetwork ?network .
  ?network a :AccessTechnology .
  FILTER(?network IN (:AccessTechnology_FIBRE, :AccessTechnology_HFC))
  ?dimensioning :hasBandwidthProfile ?profile .
  ?profile a :Cl_BandwidthProfile .
  FILTER(?profile IN (:BandwidthProfile_12_1, :BandwidthProfile_25_5, :BandwidthProfile_25_10, :BandwidthProfile_50_20, :BandwidthProfile_100_40, :BandwidthProfile_HomeFast))
}

SELECT DISTINCT ?unit WHERE {
  VALUES ?bp {
    :BandwidthProfile_12_1
    :BandwidthProfile_25_5
    :BandwidthProfile_25_10
    :BandwidthProfile_50_20
    :BandwidthProfile_100_40
    :BandwidthProfile_HomeFast
  }
  VALUES ?snr {
    :SharedNetworkResourceFibreFttc
    :SharedNetworkResourceHfc
  }
  ?td a :Cl_ThroughputDimensioning ;
     :isDimensionedOn ?snr ;
     :hasBandwidthProfile ?bp .
  OPTIONAL { ?td :hasMinimumThroughputKbps ?kbps . BIND("kbps" AS ?unit) }
  OPTIONAL { ?td :hasMinimumThroughputMbps ?mbps . BIND("Mbps" AS ?unit) }
  FILTER(BOUND(?unit))
}

PREFIX : <http://www.example.org/test#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?unit
WHERE {
  # Find Throughput Dimensioning instances for FTTB and FTTN networks
  ?td a :Cl_ThroughputDimensioning ;
      :isDimensionedOn ?sharedResource .
  ?sharedResource a :Cl_SharedNetworkResource ;
                  :appliesToNetwork :AccessTechnology_FTTB ;
                  :appliesToNetwork :AccessTechnology_FTTN .

  # Filter by the specified bandwidth profiles
  VALUES ?bp { :BandwidthProfile_12_1 :BandwidthProfile_25_5 :BandwidthProfile_25_5_10
               :BandwidthProfile_25_50_5_20 :BandwidthProfile_25_100_5_40 :BandwidthProfile_HomeFast }
  ?td :hasBandwidthProfile ?bp .

  # Get the minimum throughput property (kbps or Mbps)
  OPTIONAL { ?td :hasMinimumThroughputKbps ?kbps . BIND("kbps" AS ?unit) }
  OPTIONAL { ?td :hasMinimumThroughputMbps ?mbps . BIND("Mbps" AS ?unit) }
}

PREFIX : <http://www.example.org/test#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?minThroughput
WHERE {
  VALUES ?bp {
    :BandwidthProfile_12_1
    :BandwidthProfile_25_5
    :BandwidthProfile_25_10
    :BandwidthProfile_50_20
    :BandwidthProfile_50_100_20_40
    :BandwidthProfile_HomeFast
  }
  ?td a :Cl_ThroughputDimensioning ;
      :isDimensionedOn :SharedNetworkResourceFibreFttc ;
      :hasBandwidthProfile ?bp .
  OPTIONAL { ?td :hasMinimumThroughputKbps ?kbps . }
  OPTIONAL { ?td :hasMinimumThroughputMbps ?mbps . }
  BIND(COALESCE(?kbps, ?mbps * 1000) AS ?minThroughput)
}

